// Cron-triggered: processes queued topics (topic_queue) that are due —
// generates the post text in the requested language (+ optional image), then publishes to LinkedIn.
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { generateXaiImage } from "../_shared/xai-image.ts";
import { resolveTextProvider, xaiErrorMessage } from "../_shared/ai-text.ts";
import { resolveTargets, publishLinkedInPost } from "../_shared/linkedin.ts";
import { authorizeCronOrUser } from "../_shared/cron-auth.ts";
import { claimDueTopics, upsertAndClaimJob, finalizeJob } from "../_shared/jobs.ts";
import { makeIdempotencyKey, isPersistableImageUrl } from "../_shared/schedule-time.ts";
import { jobLog } from "../_shared/logger.ts";


const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-cron-secret",
};
const json = (s: number, b: unknown) =>
  new Response(JSON.stringify(b), { status: s, headers: { ...corsHeaders, "Content-Type": "application/json" } });

const LANG_NAMES: Record<string, string> = {
  fr: "French (Français)", en: "English", es: "Spanish (Español)",
  de: "German (Deutsch)", ar: "Arabic (العربية)",
};

async function generatePostText(opts: {
  subject: string; language: string; tone: string | null; model: string; key: string; url: string;
}): Promise<{ title: string; content: string }> {
  const langName = LANG_NAMES[opts.language] || LANG_NAMES.fr;
  const sys = `You write engaging LinkedIn posts.
LANGUAGE: Write the entire post (title, body, hashtags, CTA) strictly in ${langName}. Never use another language.
Rules: 150-300 words, 5-7 hashtags, sparing emojis, end with a CTA/question.
${opts.tone ? `Tone:\n${opts.tone}` : ""}
Return JSON via the write_post tool.`;

  const res = await fetch(opts.url, {
    method: "POST",
    headers: { Authorization: `Bearer ${opts.key}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: opts.model,
      messages: [
        { role: "system", content: sys },
        { role: "user", content: `Topic: ${opts.subject}` },
      ],
      tools: [{
        type: "function",
        function: {
          name: "write_post",
          description: "Write a LinkedIn post",
          parameters: {
            type: "object",
            properties: { title: { type: "string" }, content: { type: "string" } },
            required: ["title", "content"],
            additionalProperties: false,
          },
        },
      }],
      tool_choice: { type: "function", function: { name: "write_post" } },
    }),
  });
  if (!res.ok) throw new Error(opts.url.startsWith("https://api.x.ai/") ? xaiErrorMessage(res.status) : `AI text [${res.status}]: ${await res.text()}`);
  const data = await res.json();
  const tc = data.choices?.[0]?.message?.tool_calls?.[0];
  if (!tc) throw new Error("AI returned no structured data");
  return JSON.parse(tc.function.arguments);
}

async function generateImage(prompt: string, model: string | null, supabase: any, userId: string): Promise<string | null> {
  let base64: string;
  let mimeType = "image/png";
  if (model?.startsWith("xai/")) {
    const { data: settings, error } = await supabase.from("user_settings").select("use_byok, xai_api_key").eq("user_id", userId).maybeSingle();
    if (error) throw new Error("Impossible de charger les paramètres xAI.");
    const image = await generateXaiImage({ settings, model, prompt: `Create a professional LinkedIn post image. Subject: ${prompt}. Style: modern editorial, clean composition, premium feel.`, aspectRatio: "1:1" });
    base64 = image.base64;
    mimeType = image.mimeType;
  } else {
  const key = Deno.env.get("LOVABLE_API_KEY");
  if (!key) return null;
  const res = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
    method: "POST",
    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: model || "google/gemini-3.1-flash-image-preview",
      messages: [{ role: "user", content: `Create a professional LinkedIn post image. Subject: ${prompt}. Style: modern editorial, clean composition, premium feel.` }],
      modalities: ["image", "text"],
    }),
  });
  if (!res.ok) { console.warn("img gen fail", res.status); return null; }
  const data = await res.json();
  const dataUrl = data.choices?.[0]?.message?.images?.[0]?.image_url?.url;
  if (!dataUrl) return null;
  base64 = dataUrl.replace(/^data:image\/\w+;base64,/, "");
  }
  const bytes = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
  const fileName = `${userId}/${crypto.randomUUID()}.${mimeType === "image/jpeg" ? "jpg" : "png"}`;
  const { error } = await supabase.storage.from("post-assets").upload(fileName, bytes, { contentType: mimeType });
  if (error) return null;
  const { data: signed } = await supabase.storage.from("post-assets").createSignedUrl(fileName, 60 * 60 * 24 * 7);
  return signed?.signedUrl ?? null;
}

// Publishing is handled by the shared helper (multi-destination + retries).


async function processTopic(supabase: any, topic: any) {
  const userId = topic.user_id;
  const { data: us } = await supabase.from("user_settings")
    .select("post_model, use_byok, openai_api_key, xai_api_key, tone_instructions, image_model")
    .eq("user_id", userId).maybeSingle();

  const { model, url, key } = resolveTextProvider(us?.post_model || "google/gemini-3-flash-preview", us, Deno.env.get("LOVABLE_API_KEY"));

  const generated = await generatePostText({
    subject: topic.subject,
    language: topic.language || "fr",
    tone: us?.tone_instructions || null,
    model, key, url,
  });

  let imageUrl: string | null = null;
  if (topic.include_image) {
    imageUrl = await generateImage(topic.subject, us?.image_model ?? null, supabase, userId);
    if (!isPersistableImageUrl(imageUrl)) {
      throw new Error("IMAGE_NOT_PERSISTED: génération ou stockage image en échec.");
    }
  }

  const { targets, error: targetError } = await resolveTargets(supabase, userId, topic.target_ids);
  if (targetError || !targets.length) throw new Error(targetError || "Aucune destination LinkedIn");

  const executionId = topic.scheduled_at || topic.id;
  const results = [];
  let firstPostId: string | null = null;
  for (const target of targets) {
    const { data: insertedPost } = await supabase.from("posts").insert({
      user_id: userId,
      title: generated.title,
      content: generated.content,
      image_url: imageUrl,
      status: "processing",
      scheduled_at: topic.scheduled_at,
      target_id: target.id,
    }).select("id").single();
    const postId = insertedPost?.id ?? null;
    if (!firstPostId) firstPostId = postId;

    const idempotencyKey = makeIdempotencyKey({
      postId, targetId: target.id, executionId: `topic:${topic.id}:${executionId}`,
    });
    const claim = await upsertAndClaimJob(supabase, {
      userId, postId, targetId: target.id, topicId: topic.id, idempotencyKey, scheduledFor: topic.scheduled_at,
    });

    let r;
    if (claim.action === "already_success") {
      r = { ok: true, confirmed: true, targetId: target.id, targetName: target.name, linkedinId: claim.job.linkedin_post_urn, error: undefined };
    } else if (claim.action === "in_flight" || claim.action === "terminal_failed") {
      r = { ok: false, confirmed: false, targetId: target.id, targetName: target.name, linkedinId: undefined, error: claim.job.error_message || claim.action };
    } else {
      jobLog("JOB_STARTED", { job: claim.job.id, target: target.name, topic: topic.id });
      r = await publishLinkedInPost({
        supabase, target, content: generated.content, image: imageUrl, idempotencyKey, requireImage: !!topic.include_image,
      });
      await finalizeJob(supabase, {
        jobId: claim.job.id,
        ok: r.ok && r.confirmed,
        retryable: r.retryable,
        urn: r.linkedinId,
        errorCode: r.code,
        errorMessage: r.error,
        providerStatus: r.providerStatus,
      });
    }
    const published = !!(r.ok && r.confirmed && r.linkedinId);
    if (postId) {
      await supabase.from("posts").update({
        status: published ? "published" : "failed",
        published_at: published ? new Date().toISOString() : null,
        linkedin_post_id: r.linkedinId || null,
        error_code: published ? null : (r as any).code,
        error_message: published ? null : r.error,
      }).eq("id", postId);
    }
    results.push(r);
  }

  const okCount = results.filter((r) => r.ok && r.confirmed).length;
  const errors = results.filter((r) => !r.ok || !r.confirmed).map((r) => r.error).join(" | ");

  await supabase.from("topic_queue").update({
    status: okCount === results.length && results.length > 0 ? "published" : okCount > 0 ? "failed" : "failed",
    error: errors || null,
    post_id: firstPostId,
    processed_at: new Date().toISOString(),
  }).eq("id", topic.id);

  return { id: topic.id, ok: okCount === results.length, published: okCount, total: results.length, error: errors || undefined };

}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  try {
    const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    const caller = await authorizeCronOrUser(req, supabase);
    if (!caller) return json(401, { success: false, error: "Unauthorized" });

    let runOne: string | null = null;
    if (req.method === "POST") {
      try { const b = await req.json(); runOne = b?.topic_id || null; } catch { /* noop */ }
    }

    let due: any[] = [];
    if (runOne) {
      const q = supabase.from("topic_queue").select("*").eq("id", runOne);
      const { data } = caller.kind === "user" ? await q.eq("user_id", caller.userId).maybeSingle() : await q.maybeSingle();
      if (data) due = [data];
    } else if (caller.kind === "cron") {
      due = await claimDueTopics(supabase, 5);
    } else {
      return json(400, { success: false, error: "topic_id required for manual run" });
    }

    const results = [];
    for (const t of due) {
      if (runOne) {
        await supabase.from("topic_queue").update({ status: "generating" }).eq("id", t.id);
      }
      try {
        results.push(await processTopic(supabase, t));
      } catch (e: any) {
        console.error("topic failed", t.id, e);
        await supabase.from("topic_queue").update({
          status: "failed", error: e?.message || "Error", processed_at: new Date().toISOString(),
        }).eq("id", t.id);
        results.push({ id: t.id, ok: false, error: e?.message });
      }
    }
    return json(200, { success: true, processed: results.length, results });
  } catch (e) {
    console.error("run-topic-queue error", e);
    return json(500, { success: false, error: e instanceof Error ? e.message : "Failed" });
  }
});

type LogFields = Record<string, unknown>;

function sanitize(fields: LogFields): LogFields {
  const out: LogFields = {};
  for (const [k, v] of Object.entries(fields)) {
    const key = k.toLowerCase();
    if (key.includes("token") || key.includes("secret") || key.includes("authorization") || key.includes("password") || key.includes("apikey") || key.includes("api_key")) {
      continue;
    }
    out[k] = v;
  }
  return out;
}

export function jobLog(event: string, fields: LogFields = {}) {
  console.log(JSON.stringify({ event, ts: new Date().toISOString(), ...sanitize(fields) }));
}

const WEEKDAY: Record<string, number> = {
  Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7,
};

export function wallTimeToUtc(localIsoDate: string, hour: number, minute: number, timeZone: string): Date {
  const hh = String(hour).padStart(2, "0");
  const mi = String(minute).padStart(2, "0");
  const local = `${localIsoDate}T${hh}:${mi}:00`;
  const asUtc = new Date(`${local}Z`).getTime();
  const tzString = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).format(new Date(asUtc));
  const m = tzString.match(/(\d{2})\/(\d{2})\/(\d{4}),?\s+(\d{2}):(\d{2})/);
  let offsetMin = 0;
  if (m) {
    const tzAsUtc = Date.UTC(+m[3], +m[1] - 1, +m[2], +m[4], +m[5]);
    offsetMin = (asUtc - tzAsUtc) / 60000;
  }
  return new Date(asUtc + offsetMin * 60000);
}

export function computeNextRun(
  daysOfWeek: number[],
  hour: number,
  minute: number,
  timeZone: string,
  from: Date = new Date(),
): Date {
  if (!daysOfWeek?.length) return new Date(from.getTime() + 24 * 3600_000);
  const days = new Set(daysOfWeek);
  for (let i = 0; i < 14; i++) {
    const candidate = new Date(from.getTime() + i * 24 * 3600_000);
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone,
      weekday: "short",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(candidate).reduce<Record<string, string>>((acc, p) => {
      acc[p.type] = p.value;
      return acc;
    }, {});
    const wd = WEEKDAY[parts.weekday];
    if (!days.has(wd)) continue;
    const target = wallTimeToUtc(`${parts.year}-${parts.month}-${parts.day}`, hour, minute, timeZone);
    if (target.getTime() > from.getTime()) return target;
  }
  return new Date(from.getTime() + 24 * 3600_000);
}

export function makeIdempotencyKey(parts: {
  postId?: string | null;
  targetId: string;
  scheduleId?: string | null;
  executionId: string;
}): string {
  return [
    parts.scheduleId ? `sched:${parts.scheduleId}` : "oneshot",
    parts.postId ? `post:${parts.postId}` : "nopost",
    `target:${parts.targetId}`,
    `exec:${parts.executionId}`,
  ].join("|");
}

export function isPersistableImageUrl(url: string | null | undefined): boolean {
  if (!url) return false;
  if (url.startsWith("data:")) return false;
  return url.startsWith("https://") || url.startsWith("http://");
}

import { jobLog } from "./logger.ts";

export type ClaimAction = "claimed" | "already_success" | "in_flight" | "terminal_failed";

export type PublicationJob = {
  id: string;
  user_id: string;
  post_id: string | null;
  target_id: string | null;
  schedule_id: string | null;
  topic_id: string | null;
  idempotency_key: string;
  status: string;
  attempt_count: number;
  scheduled_for: string | null;
  started_at: string | null;
  completed_at: string | null;
  linkedin_post_urn: string | null;
  error_code: string | null;
  error_message: string | null;
  last_attempt_at: string | null;
};

export async function upsertAndClaimJob(supabase: any, args: {
  userId: string;
  postId?: string | null;
  targetId: string;
  scheduleId?: string | null;
  topicId?: string | null;
  idempotencyKey: string;
  scheduledFor?: string | null;
}): Promise<{ action: ClaimAction; job: PublicationJob }> {
  const { data, error } = await supabase.rpc("upsert_and_claim_publication_job", {
    p_user_id: args.userId,
    p_post_id: args.postId ?? null,
    p_target_id: args.targetId,
    p_schedule_id: args.scheduleId ?? null,
    p_topic_id: args.topicId ?? null,
    p_idempotency_key: args.idempotencyKey,
    p_scheduled_for: args.scheduledFor ?? null,
  });
  if (error) throw new Error(`claim job failed: ${error.message}`);
  const action = (data?.action ?? "in_flight") as ClaimAction;
  const job = data?.job as PublicationJob;
  jobLog("JOB_CLAIM", { action, job: job?.id, key: args.idempotencyKey, target: args.targetId });
  return { action, job };
}

export async function finalizeJob(supabase: any, args: {
  jobId: string;
  ok: boolean;
  retryable: boolean;
  urn?: string | null;
  errorCode?: string | null;
  errorMessage?: string | null;
  providerStatus?: number | null;
  providerResponse?: Record<string, unknown> | null;
}): Promise<PublicationJob> {
  const { data, error } = await supabase.rpc("finalize_publication_job", {
    p_job_id: args.jobId,
    p_ok: args.ok,
    p_retryable: args.retryable,
    p_urn: args.urn ?? null,
    p_error_code: args.errorCode ?? null,
    p_error_message: args.errorMessage ?? null,
    p_provider_status: args.providerStatus ?? null,
    p_provider_response: args.providerResponse ?? null,
  });
  if (error) throw new Error(`finalize job failed: ${error.message}`);
  jobLog(args.ok ? "JOB_SUCCESS" : args.retryable ? "JOB_RETRYING" : "JOB_FAILED", {
    job: args.jobId,
    urn: args.urn ?? undefined,
    code: args.errorCode ?? undefined,
  });
  return data as PublicationJob;
}

export async function claimDueSchedules(supabase: any, limit = 5) {
  const { data, error } = await supabase.rpc("claim_due_schedules", { p_limit: limit });
  if (error) throw new Error(error.message);
  return (data ?? []) as any[];
}

export async function claimDueScheduledPosts(supabase: any, limit = 10) {
  const { data, error } = await supabase.rpc("claim_due_scheduled_posts", { p_limit: limit });
  if (error) throw new Error(error.message);
  return (data ?? []) as any[];
}

export async function claimDueTopics(supabase: any, limit = 5) {
  const { data, error } = await supabase.rpc("claim_due_topics", { p_limit: limit });
  if (error) throw new Error(error.message);
  return (data ?? []) as any[];
}

import type { createClient } from "https://esm.sh/@supabase/supabase-js@2";

type Supabase = ReturnType<typeof createClient>;

export type Caller =
  | { kind: "cron" }
  | { kind: "user"; userId: string };

export async function authorizeCronOrUser(req: Request, supabase: Supabase): Promise<Caller | null> {
  const cronHeader = req.headers.get("x-cron-secret") || "";
  const auth = req.headers.get("authorization") || "";
  const bearer = auth.startsWith("Bearer ") ? auth.slice(7) : "";

  const envSecret = Deno.env.get("CRON_SECRET") || "";
  if (envSecret && (cronHeader === envSecret || bearer === envSecret)) {
    return { kind: "cron" };
  }

  const { data: cfg } = await supabase.from("automation_config").select("cron_secret").eq("id", 1).maybeSingle();
  const stored = (cfg as { cron_secret?: string } | null)?.cron_secret || "";
  if (stored && (cronHeader === stored || bearer === stored)) {
    return { kind: "cron" };
  }

  if (bearer && bearer !== envSecret && bearer !== stored) {
    const { data, error } = await supabase.auth.getUser(bearer);
    if (!error && data.user?.id) return { kind: "user", userId: data.user.id };
  }
  return null;
}

export async function requireUser(req: Request, supabase: Supabase): Promise<string | null> {
  const auth = req.headers.get("authorization") || "";
  if (!auth.startsWith("Bearer ")) return null;
  const { data, error } = await supabase.auth.getUser(auth.slice(7));
  if (error || !data.user?.id) return null;
  return data.user.id;
}

// LinkedIn publishing: Posts API (/rest/posts) with Images API upload.
// ugcPosts is only a last-resort fallback for member posts when /rest/posts is unavailable.

import { jobLog } from "./logger.ts";
import { isPersistableImageUrl } from "./schedule-time.ts";

export const LINKEDIN_VERSION = "202608";

export type LinkedInTarget = {
  id: string;
  user_id: string;
  kind: "person" | "organization" | string;
  urn: string;
  name: string;
  access_token: string | null;
  refresh_token?: string | null;
  token_expires_at: string | null;
  status: string;
  is_default: boolean;
};

export type PublishErrorCode =
  | "LINKEDIN_TOKEN_EXPIRED"
  | "LINKEDIN_NOT_CONNECTED"
  | "LINKEDIN_FORBIDDEN"
  | "LINKEDIN_API_ERROR"
  | "LINKEDIN_RATE_LIMITED"
  | "LINKEDIN_TRANSIENT"
  | "INVALID_CONTENT"
  | "IMAGE_REQUIRED"
  | "IMAGE_NOT_PERSISTED"
  | "TARGET_INVALID"
  | "NETWORK_ERROR"
  | "TIMEOUT";

export type PublishResult = {
  ok: boolean;
  targetId: string;
  targetName: string;
  linkedinId?: string;
  error?: string;
  code?: PublishErrorCode;
  attempts: number;
  retryable: boolean;
  providerStatus?: number;
  confirmed: boolean;
};

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export const normalizeUrn = (urn: string, kind: string) => {
  if (urn.startsWith("urn:li:")) return urn;
  return kind === "organization" ? `urn:li:organization:${urn}` : `urn:li:person:${urn}`;
};

function restHeaders(accessToken: string, extra: Record<string, string> = {}) {
  return {
    Authorization: `Bearer ${accessToken}`,
    "Content-Type": "application/json",
    "X-Restli-Protocol-Version": "2.0.0",
    "Linkedin-Version": LINKEDIN_VERSION,
    ...extra,
  };
}

function classifyStatus(status: number, body: string): { code: PublishErrorCode; retryable: boolean } {
  if (status === 401) return { code: "LINKEDIN_TOKEN_EXPIRED", retryable: false };
  if (status === 403) return { code: "LINKEDIN_FORBIDDEN", retryable: false };
  if (status === 429) return { code: "LINKEDIN_RATE_LIMITED", retryable: true };
  if (status === 400) {
    const invalid = /invalid|commentary|author|validation|DUPLICATE/i.test(body);
    return { code: invalid ? "INVALID_CONTENT" : "LINKEDIN_API_ERROR", retryable: false };
  }
  if (status === 502 || status === 503 || status === 504 || status >= 500) {
    return { code: "LINKEDIN_TRANSIENT", retryable: true };
  }
  return { code: "LINKEDIN_API_ERROR", retryable: false };
}

export async function resolveTargets(
  supabase: any,
  userId: string,
  targetIds?: (string | null | undefined)[] | null,
): Promise<{ targets: LinkedInTarget[]; error?: string }> {
  const ids = (targetIds ?? []).filter((v): v is string => !!v);

  if (ids.length) {
    const { data } = await supabase
      .from("linkedin_targets").select("*").eq("user_id", userId).in("id", ids);
    const targets = (data ?? []) as LinkedInTarget[];
    if (!targets.length) return { targets: [], error: "Destination LinkedIn introuvable ou supprimée." };
    return { targets };
  }

  const { data: all } = await supabase
    .from("linkedin_targets").select("*").eq("user_id", userId)
    .order("is_default", { ascending: false })
    .order("created_at", { ascending: true });
  const targets = (all ?? []) as LinkedInTarget[];
  if (!targets.length) {
    return { targets: [], error: "Aucune destination LinkedIn connectée. Va dans Réglages → Destinations LinkedIn." };
  }
  return { targets: [targets[0]] };
}

async function markTargetExpired(supabase: any, targetId: string) {
  await supabase.from("linkedin_targets").update({ status: "expired" }).eq("id", targetId);
}

async function refreshAccessToken(
  supabase: any,
  target: LinkedInTarget,
): Promise<{ accessToken: string; expiresAt: string | null } | null> {
  if (!target.refresh_token) return null;
  const { data: settings } = await supabase
    .from("user_settings")
    .select("linkedin_client_id, linkedin_client_secret")
    .eq("user_id", target.user_id)
    .maybeSingle();
  const clientId = settings?.linkedin_client_id || Deno.env.get("LINKEDIN_CLIENT_ID");
  const clientSecret = settings?.linkedin_client_secret || Deno.env.get("LINKEDIN_CLIENT_SECRET");
  if (!clientId || !clientSecret) return null;

  const res = await fetch("https://www.linkedin.com/oauth/v2/accessToken", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "refresh_token",
      refresh_token: target.refresh_token,
      client_id: clientId,
      client_secret: clientSecret,
    }),
  });
  if (!res.ok) {
    jobLog("LINKEDIN_REFRESH_FAILED", { target: target.id, status: res.status });
    return null;
  }
  const data = await res.json();
  const accessToken = data.access_token as string;
  const expiresAt = data.expires_in
    ? new Date(Date.now() + Number(data.expires_in) * 1000).toISOString()
    : null;
  const refreshToken = (data.refresh_token as string | undefined) || target.refresh_token;
  await supabase.from("linkedin_targets").update({
    access_token: accessToken,
    refresh_token: refreshToken,
    token_expires_at: expiresAt,
    status: "connected",
  }).eq("id", target.id);
  jobLog("LINKEDIN_TOKEN_REFRESHED", { target: target.id });
  return { accessToken, expiresAt };
}

async function ensureFreshToken(supabase: any, target: LinkedInTarget): Promise<
  { ok: true; accessToken: string } | { ok: false; result: PublishResult }
> {
  const base = { targetId: target.id, targetName: target.name, attempts: 0, confirmed: false, retryable: false };
  if (!target.access_token && !target.refresh_token) {
    return {
      ok: false,
      result: { ...base, ok: false, code: "LINKEDIN_NOT_CONNECTED", error: `${target.name} : jeton LinkedIn absent. Reconnecte cette destination.` },
    };
  }

  const expiringSoon = target.token_expires_at
    && Date.parse(target.token_expires_at) <= Date.now() + 5 * 60_000;
  if (expiringSoon || !target.access_token) {
    const refreshed = await refreshAccessToken(supabase, target);
    if (refreshed) return { ok: true, accessToken: refreshed.accessToken };
    if (target.token_expires_at && Date.parse(target.token_expires_at) <= Date.now()) {
      await markTargetExpired(supabase, target.id);
      return {
        ok: false,
        result: { ...base, ok: false, code: "LINKEDIN_TOKEN_EXPIRED", error: `${target.name} : connexion LinkedIn expirée. Reconnecte cette destination.` },
      };
    }
  }
  return { ok: true, accessToken: target.access_token! };
}

async function uploadImagePostsApi(accessToken: string, owner: string, imageUrl: string): Promise<string | null> {
  const init = await fetch("https://api.linkedin.com/rest/images?action=initializeUpload", {
    method: "POST",
    headers: restHeaders(accessToken),
    body: JSON.stringify({ initializeUploadRequest: { owner } }),
  });
  if (!init.ok) {
    jobLog("IMAGE_INIT_FAILED", { status: init.status, api: "rest/images" });
    return null;
  }
  const rd = await init.json();
  const uploadUrl = rd.value?.uploadUrl;
  const imageUrn = rd.value?.image;
  if (!uploadUrl || !imageUrn) return null;

  const blob = await (await fetch(imageUrl)).blob();
  const put = await fetch(uploadUrl, {
    method: "PUT",
    headers: { Authorization: `Bearer ${accessToken}` },
    body: blob,
  });
  if (!put.ok) {
    jobLog("IMAGE_PUT_FAILED", { status: put.status });
    return null;
  }
  return imageUrn as string;
}

async function uploadImageLegacy(accessToken: string, owner: string, imageUrl: string): Promise<string | null> {
  const reg = await fetch("https://api.linkedin.com/v2/assets?action=registerUpload", {
    method: "POST",
    headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      registerUploadRequest: {
        recipes: ["urn:li:digitalmediaRecipe:feedshare-image"],
        owner,
        serviceRelationships: [{ relationshipType: "OWNER", identifier: "urn:li:userGeneratedContent" }],
      },
    }),
  });
  if (!reg.ok) return null;
  const rd = await reg.json();
  const uploadUrl = rd.value?.uploadMechanism?.["com.linkedin.digitalmedia.uploading.MediaUploadHttpRequest"]?.uploadUrl;
  const asset = rd.value?.asset ?? null;
  if (!uploadUrl || !asset) return null;
  const blob = await (await fetch(imageUrl)).blob();
  const put = await fetch(uploadUrl, {
    method: "PUT",
    headers: { Authorization: `Bearer ${accessToken}` },
    body: blob,
  });
  return put.ok ? (asset as string) : null;
}

async function createRestPost(
  accessToken: string,
  author: string,
  content: string,
  imageUrn: string | null,
  idempotencyKey?: string,
): Promise<{ ok: true; urn: string; status: number } | { ok: false; status: number; body: string }> {
  const body: Record<string, unknown> = {
    author,
    commentary: content,
    visibility: "PUBLIC",
    distribution: {
      feedDistribution: "MAIN_FEED",
      targetEntities: [],
      thirdPartyDistributionChannels: [],
    },
    lifecycleState: "PUBLISHED",
    isReshareDisabledByAuthor: false,
  };
  if (imageUrn) {
    body.content = { media: { id: imageUrn } };
  }

  const headers = restHeaders(accessToken);
  if (idempotencyKey) headers["X-Restli-Idempotency-Key"] = idempotencyKey.slice(0, 32);

  const res = await fetch("https://api.linkedin.com/rest/posts", {
    method: "POST",
    headers,
    body: JSON.stringify(body),
  });

  const text = await res.text();
  if (res.ok || res.status === 201) {
    const urn = res.headers.get("x-restli-id") || (() => {
      try { return JSON.parse(text).id; } catch { return null; }
    })();
    if (!urn) return { ok: false, status: res.status, body: text || "LinkedIn n'a pas renvoyé d'identifiant de post." };
    return { ok: true, urn, status: res.status };
  }
  return { ok: false, status: res.status, body: text };
}

async function createUgcPost(
  accessToken: string,
  author: string,
  content: string,
  asset: string | null,
): Promise<{ ok: true; urn: string; status: number } | { ok: false; status: number; body: string }> {
  const body = {
    author,
    lifecycleState: "PUBLISHED",
    specificContent: {
      "com.linkedin.ugc.ShareContent": {
        shareCommentary: { text: content },
        shareMediaCategory: asset ? "IMAGE" : "NONE",
        ...(asset ? { media: [{ status: "READY", media: asset }] } : {}),
      },
    },
    visibility: { "com.linkedin.ugc.MemberNetworkVisibility": "PUBLIC" },
  };
  const res = await fetch("https://api.linkedin.com/v2/ugcPosts", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      "X-Restli-Protocol-Version": "2.0.0",
    },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  if (res.ok) {
    let urn: string | undefined;
    try { urn = JSON.parse(text).id; } catch { /* ignore */ }
    if (!urn) return { ok: false, status: res.status, body: text || "LinkedIn n'a pas renvoyé d'identifiant de post." };
    return { ok: true, urn, status: res.status };
  }
  return { ok: false, status: res.status, body: text };
}

export async function publishLinkedInPost(opts: {
  supabase: any;
  target: LinkedInTarget;
  content: string;
  image?: string | null;
  idempotencyKey?: string;
  requireImage?: boolean;
  maxAttempts?: number;
}): Promise<PublishResult> {
  const { supabase, target, content, image, idempotencyKey, requireImage, maxAttempts = 3 } = opts;
  const base = { targetId: target.id, targetName: target.name, confirmed: false };

  if (!target.urn) {
    return { ...base, ok: false, attempts: 0, retryable: false, code: "TARGET_INVALID", error: `${target.name} : URN organisation/profil manquant.` };
  }
  if (!content?.trim()) {
    return { ...base, ok: false, attempts: 0, retryable: false, code: "INVALID_CONTENT", error: "Le contenu du post est vide." };
  }

  const token = await ensureFreshToken(supabase, target);
  if (!token.ok) return token.result;
  const accessToken = token.accessToken;
  const author = normalizeUrn(target.urn, target.kind);

  let imageUrn: string | null = null;
  if (image) {
    if (!isPersistableImageUrl(image)) {
      return {
        ...base, ok: false, attempts: 0, retryable: false, code: "IMAGE_NOT_PERSISTED",
        error: "L'image n'est pas une URL persistante (data: refusée). Régénère ou téléverse l'image.",
      };
    }
    jobLog("IMAGE_UPLOAD_START", { target: target.id });
    imageUrn = await uploadImagePostsApi(accessToken, author, image);
    if (!imageUrn) imageUrn = await uploadImageLegacy(accessToken, author, image);
    if (!imageUrn) {
      return {
        ...base, ok: false, attempts: 0, retryable: true, code: "IMAGE_NOT_PERSISTED",
        error: "Échec de l'upload image vers LinkedIn.",
      };
    }
    jobLog("IMAGE_READY", { target: target.id });
  } else if (requireImage) {
    return {
      ...base, ok: false, attempts: 0, retryable: false, code: "IMAGE_REQUIRED",
      error: "Image requise pour cette publication, absente ou non persistée.",
    };
  }

  let lastError = "Échec de publication LinkedIn";
  let lastStatus = 0;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    jobLog("PUBLISH_REQUEST", { target: target.id, attempt, api: "rest/posts" });
    let created = await createRestPost(accessToken, author, content, imageUrn, idempotencyKey);

    const restUnavailable = !created.ok && (created.status === 404 || created.status === 410 ||
      (created.status === 403 && /PRODUCT|version|not enabled/i.test(created.body)));
    if (restUnavailable && target.kind === "person") {
      jobLog("PUBLISH_FALLBACK_UGC", { target: target.id, status: created.status });
      created = await createUgcPost(accessToken, author, content, imageUrn);
    }

    if (created.ok) {
      await supabase.from("linkedin_targets").update({ status: "connected" }).eq("id", target.id);
      jobLog("LINKEDIN_RESPONSE", { target: target.id, status: created.status, urn: created.urn });
      return {
        ...base, ok: true, attempts: attempt, linkedinId: created.urn,
        confirmed: true, retryable: false, providerStatus: created.status,
      };
    }

    lastStatus = created.status;
    lastError = `LinkedIn [${created.status}] ${created.body}`.slice(0, 800);
    const classified = classifyStatus(created.status, created.body);
    jobLog("LINKEDIN_ERROR", { target: target.id, status: created.status, attempt, code: classified.code });

    if (classified.code === "LINKEDIN_TOKEN_EXPIRED") {
      await markTargetExpired(supabase, target.id);
      return { ...base, ok: false, attempts: attempt, code: classified.code, error: `${target.name} : jeton LinkedIn invalide. Reconnecte cette destination.`, retryable: false, providerStatus: created.status };
    }
    if (!classified.retryable || attempt === maxAttempts) {
      return { ...base, ok: false, attempts: attempt, code: classified.code, error: lastError, retryable: classified.retryable && attempt < maxAttempts, providerStatus: created.status };
    }
    await sleep(attempt * 1500);
  }

  return { ...base, ok: false, attempts: maxAttempts, code: "LINKEDIN_TRANSIENT", error: lastError, retryable: true, providerStatus: lastStatus };
}

/** Backward-compatible wrapper used by existing callers. */
export async function publishToTarget(
  supabase: any,
  target: LinkedInTarget,
  content: string,
  imageUrl: string | null,
  maxAttempts = 3,
): Promise<PublishResult> {
  return publishLinkedInPost({ supabase, target, content, image: imageUrl, maxAttempts });
}

export async function publishToTargets(
  supabase: any,
  targets: LinkedInTarget[],
  content: string,
  imageUrl: string | null,
): Promise<PublishResult[]> {
  const results: PublishResult[] = [];
  for (const t of targets) {
    results.push(await publishToTarget(supabase, t, content, imageUrl));
  }
  return results;
}

export type TextSettings = {
  use_byok?: boolean;
  openai_api_key?: string | null;
  xai_api_key?: string | null;
};

export function resolveTextProvider(model: string, settings: TextSettings | null, lovableKey?: string) {
  if (model.startsWith("xai/")) {
    if (!settings?.use_byok) throw new Error("Active tes propres clés API dans les paramètres pour utiliser Grok.");
    if (!settings.xai_api_key?.trim()) throw new Error("Ajoute et enregistre ta clé API xAI dans les paramètres pour utiliser Grok.");
    return { model: model.slice(4), url: "https://api.x.ai/v1/chat/completions", key: settings.xai_api_key.trim() };
  }
  if (settings?.use_byok && model.startsWith("openai/") && settings.openai_api_key) {
    return { model: model.slice(7), url: "https://api.openai.com/v1/chat/completions", key: settings.openai_api_key };
  }
  if (!lovableKey) throw new Error("Aucune clé Lovable AI disponible.");
  return { model, url: "https://ai.gateway.lovable.dev/v1/chat/completions", key: lovableKey };
}

export function normalizeGrokModels(models: unknown, modality: "text" | "image" = "text"): { value: string; label: string }[] {
  if (!Array.isArray(models)) return [];
  const ids = new Set<string>();
  for (const model of models) {
    if (!model || typeof model !== "object") continue;
    const { id, aliases, output_modalities } = model;
    if (Array.isArray(output_modalities) && !output_modalities.includes(modality)) continue;
    for (const name of [id, ...(Array.isArray(aliases) ? aliases : [])]) {
      if (typeof name === "string" && /^[a-zA-Z0-9._-]+$/.test(name)) ids.add(name);
    }
  }
  return [...ids].sort().map((id) => ({ value: `xai/${id}`, label: `Grok · ${id} (API xAI)` }));
}

export function xaiErrorMessage(status: number) {
  if (status === 401) return "Clé API xAI invalide ou expirée. Remplace-la dans les paramètres.";
  if (status === 402) return "Crédits xAI insuffisants. Recharge ton compte xAI.";
  if (status === 403) return "Accès xAI refusé : vérifie les permissions de ta clé et l’accès au modèle.";
  if (status === 404) return "Ce modèle Grok n’est plus disponible. Actualise la liste dans les paramètres.";
  if (status === 429) return "Limite de requêtes xAI atteinte. Réessaie plus tard.";
  if (status === 503) return "Le modèle Grok est temporairement surchargé. Réessaie plus tard.";
  return `La requête xAI a échoué (${status}). Vérifie le modèle et réessaie.`;
}

import { xaiErrorMessage } from "./ai-text.ts";

type XaiImageOptions = {
  settings: { use_byok?: boolean | null; xai_api_key?: string | null } | null;
  model: string;
  prompt: string;
  aspectRatio?: string;
  inputImageUrl?: string;
};

const XAI_RATIOS = ["1:1", "3:4", "4:3", "9:16", "16:9", "2:3", "3:2", "1:2", "2:1"];

export function normalizeXaiAspectRatio(input?: string): string {
  const m = (input || "").match(/(\d+(?:\.\d+)?)\s*:\s*(\d+(?:\.\d+)?)/);
  if (!m) return "1:1";
  const exact = `${m[1]}:${m[2]}`;
  if (XAI_RATIOS.includes(exact)) return exact;
  const target = Number(m[1]) / Number(m[2]);
  let best = "1:1", diff = Infinity;
  for (const r of XAI_RATIOS) {
    const [a, b] = r.split(":").map(Number);
    const d = Math.abs(a / b - target);
    if (d < diff) { diff = d; best = r; }
  }
  return best;
}

export function buildXaiImageRequest(opts: XaiImageOptions) {
  if (!opts.settings?.use_byok) throw new Error("Active tes propres clés API pour utiliser les images Grok.");
  if (!opts.settings.xai_api_key?.trim()) throw new Error("Ajoute et enregistre ta clé API xAI dans les paramètres.");
  if (!/^xai\/[a-zA-Z0-9._-]+$/.test(opts.model)) throw new Error("Modèle d’image xAI invalide.");
  return {
    url: `https://api.x.ai/v1/images/${opts.inputImageUrl ? "edits" : "generations"}`,
    body: {
      model: opts.model.slice(4), prompt: opts.prompt.slice(0, 8000), n: 1,
      response_format: "b64_json", aspect_ratio: normalizeXaiAspectRatio(opts.aspectRatio),
      ...(opts.inputImageUrl ? { image: { type: "image_url", url: opts.inputImageUrl } } : {}),
    },
  };
}

export async function generateXaiImage(opts: XaiImageOptions): Promise<{ base64: string; mimeType: string }> {
  const request = buildXaiImageRequest(opts);
  const key = opts.settings?.xai_api_key?.trim();
  const response = await fetch(request.url, {
    method: "POST", headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
    body: JSON.stringify(request.body),
  });
  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    console.error("xAI image error", response.status, detail.slice(0, 500));
    throw new Error(xaiErrorMessage(response.status));
  }
  const data = await response.json();
  const image = data.data?.[0];
  if (typeof image?.b64_json !== "string" || !image.b64_json) throw new Error("xAI n’a retourné aucune image.");
  // xAI image endpoints return JPEG data by default; retain PNG if detected.
  const mimeType = image.b64_json.startsWith("iVBORw0KGgo") ? "image/png" : "image/jpeg";
  return { base64: image.b64_json, mimeType };
}
